open("app/src/main/AndroidManifest.xml","w").write('<manifest xmlns:android="http://schemas.android.com/apk/res/android"><application android:label="OTG Flasher"><activity android:name=".MainActivity" android:exported="true"><intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter></activity></application></manifest>')
open("app/src/main/res/layout/activity_main.xml","w").write('<?xml version="1.0"?><LinearLayout xmlns:android="http://schemas.android.com/apk/res/android" android:layout_width="match_parent" android:layout_height="match_parent" android:background="#020A1A" android:orientation="vertical"><TextView android:layout_width="match_parent" android:layout_height="wrap_content" android:text="OTG FLASHER v2 - BOOT/RECOVERY/SYSTEM/VENDOR/USERDATA/VBMETA" android:textColor="#00D4FF" android:gravity="center" android:padding="12dp" android:textStyle="bold"/><TextView android:id="@+id/tv" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="Ready - Pick IMG" android:textColor="#FFAA00" android:padding="8dp"/><Button android:id="@+id/b1" android:layout_width="match_parent" android:layout_height="50dp" android:text="PICK IMG &amp; FLASH TO BOOT" android:layout_margin="5dp"/><Button android:id="@+id/b2" android:layout_width="match_parent" android:layout_height="50dp" android:text="FLASH RECOVERY" android:layout_margin="5dp"/><Button android:id="@+id/b3" android:layout_width="match_parent" android:layout_height="50dp" android:text="FLASH SYSTEM" android:layout_margin="5dp"/><Button android:id="@+id/b4" android:layout_width="match_parent" android:layout_height="50dp" android:text="FLASH VENDOR" android:layout_margin="5dp"/><Button android:id="@+id/b5" android:layout_width="match_parent" android:layout_height="50dp" android:text="FLASH USERDATA - WIPE" android:layout_margin="5dp"/><TextView android:id="@+id/log" android:layout_width="match_parent" android:layout_height="300dp" android:background="#000" android:textColor="#0F0" android:text="> Ready" android:fontFamily="monospace" android:padding="8dp"/></LinearLayout>')
open("app/src/main/java/com/otgflasher/pro/MainActivity.java","w").write('package com.otgflasher.pro;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;public class MainActivity extends AppCompatActivity{TextView log,tv;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);log=findViewById(R.id.log);tv=findViewById(R.id.tv);findViewById(R.id.b1).setOnClickListener(v->{log.append("\\n$ flash boot");});}}')
